const agentData = $input.first().json.output || $input.first().json;

if (!agentData || !agentData.proposal) {
  throw new Error('Agent-Output ungueltig oder kein proposal-Feld: ' + JSON.stringify(agentData).slice(0, 200));
}

const state = $('Parse LLM output to JSON').first().json.state;
const anfrage = state.anfrage;
const kunde = state.kunde;
const pauschale = $('Prepare Budget').first().json.pauschale || 200;
const guestCount = anfrage.personenanzahl;
const budget = anfrage.budget;

let menuGesamtpreis = 0;

const proposal = agentData.proposal.map(function(item) {
  const count = item.count || guestCount;
  const totalPrice = Math.round(item.pricePerPerson * count * 100) / 100;
  menuGesamtpreis += totalPrice;
  const isAllergikerAlternative = count < guestCount;
  return {
    menuItemId: item.menuItemId,
    name: item.name,
    category: item.category,
    count: count,
    pricePerPerson: Math.round(item.pricePerPerson * 100) / 100,
    totalPrice: totalPrice,
    reason: item.reason || '',
    isAllergikerAlternative: isAllergikerAlternative
  };
});

menuGesamtpreis = Math.round(menuGesamtpreis * 100) / 100;
const totalCosts = Math.round((menuGesamtpreis + pauschale) * 100) / 100;
const budgetEingehalten = totalCosts <= budget;

const summary = {
  proposal, guestCount, menuGesamtpreis,
  verwaltungspauschale: pauschale, totalCosts, budget,
  budgetEingehalten, reason: agentData.reason || ''
};

function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function valueOrFallback(val, fallback) {
  if (val === null || val === undefined || val === '') return fallback || 'nicht angegeben';
  return val;
}

const datumDisplay = anfrage.datum_iso
  ? escapeHtml(anfrage.datum_text) + ' <span style="color:#888;">(konkret: ' + escapeHtml(anfrage.datum_iso) + ')</span>'
  : escapeHtml(valueOrFallback(anfrage.datum_text));

const uhrzeitDisplay = anfrage.uhrzeit_iso
  ? escapeHtml(anfrage.uhrzeit_text) + ' <span style="color:#888;">(konkret: ' + escapeHtml(anfrage.uhrzeit_iso) + ')</span>'
  : escapeHtml(valueOrFallback(anfrage.uhrzeit_text));

const summaryRows = [
  ['Name', escapeHtml(valueOrFallback(kunde.telegram_name))],
  ['Anlass', escapeHtml(valueOrFallback(anfrage.anlass))],
  ['Datum', datumDisplay],
  ['Uhrzeit', uhrzeitDisplay],
  ['Personenanzahl', escapeHtml(String(anfrage.personenanzahl))],
  ['Ort', escapeHtml(valueOrFallback(anfrage.ort))],
  ['Budget', 'EUR ' + Number(budget).toFixed(2)],
  ['Speisewuensche', escapeHtml(valueOrFallback(anfrage.speisen_wuensche))],
  ['Allergien', escapeHtml(valueOrFallback(anfrage.allergien, 'keine'))],
  ['Sonstige Wuensche', escapeHtml(valueOrFallback(anfrage.sonstige_wuensche, 'keine'))]
];

const summaryTable = '<table style="width:100%;border-collapse:collapse;font-size:14px;">'
  + summaryRows.map(function(row) {
      return '<tr>'
        + '<td style="padding:6px 12px 6px 0;color:#666;width:160px;vertical-align:top;">' + row[0] + ':</td>'
        + '<td style="padding:6px 0;color:#222;vertical-align:top;">' + row[1] + '</td>'
        + '</tr>';
    }).join('')
  + '</table>';

const dishCards = proposal.map(function(i, idx) {
  const allergikerBadge = i.isAllergikerAlternative
    ? '<span style="display:inline-block;background:#fff3cd;color:#856404;padding:2px 8px;border-radius:4px;font-size:12px;font-weight:bold;margin-left:8px;">ALLERGIKER-ALTERNATIVE</span>'
    : '';
  const reasonHtml = i.reason
    ? '<div style="margin-top:8px;padding-top:8px;border-top:1px solid #eee;color:#555;font-size:13px;font-style:italic;">' + escapeHtml(i.reason) + '</div>'
    : '';
  return ''
    + '<div style="border:1px solid #e0e0e0;border-radius:8px;padding:14px 16px;margin-bottom:12px;background:#fafafa;">'
    +   '<div style="font-size:15px;font-weight:bold;color:#222;margin-bottom:8px;">'
    +     (idx + 1) + '. ' + escapeHtml(i.name) + allergikerBadge
    +   '</div>'
    +   '<table style="width:100%;border-collapse:collapse;font-size:13px;color:#333;">'
    +     '<tr><td style="padding:2px 0;width:160px;color:#666;">Kategorie:</td><td style="padding:2px 0;">' + escapeHtml(i.category) + '</td></tr>'
    +     '<tr><td style="padding:2px 0;color:#666;">Preis pro Person:</td><td style="padding:2px 0;">EUR ' + i.pricePerPerson.toFixed(2) + '</td></tr>'
    +     '<tr><td style="padding:2px 0;color:#666;">Anzahl:</td><td style="padding:2px 0;">' + i.count + ' Personen</td></tr>'
    +     '<tr><td style="padding:2px 0;color:#666;">Gesamt:</td><td style="padding:2px 0;font-weight:bold;">EUR ' + i.totalPrice.toFixed(2) + '</td></tr>'
    +   '</table>'
    +   reasonHtml
    + '</div>';
}).join('');

const budgetBadge = budgetEingehalten
  ? '<span style="display:inline-block;background:#d4edda;color:#155724;padding:4px 12px;border-radius:4px;font-weight:bold;">JA</span>'
  : '<span style="display:inline-block;background:#f8d7da;color:#721c24;padding:4px 12px;border-radius:4px;font-weight:bold;">NEIN - Ueberschreitung!</span>';

const sectionHeader = function(title) {
  return '<h2 style="background:#2c3e50;color:white;padding:12px 16px;margin:24px 0 16px 0;border-radius:8px;font-size:18px;">' + title + '</h2>';
};

const emailBody = ''
  + '<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;margin:0 auto;color:#222;">'
  +   '<h2 style="background:#2c3e50;color:white;padding:12px 16px;margin:0 0 16px 0;border-radius:8px;font-size:18px;">Zusammenfassung der Anfrage</h2>'
  +   summaryTable
  +   sectionHeader('Ausgewaehlte Gerichte')
  +   dishCards
  +   sectionHeader('Kostenuebersicht')
  +   '<table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:8px;">'
  +     '<tr><td style="padding:6px 0;color:#666;">Menuepreise gesamt:</td><td style="padding:6px 0;text-align:right;">EUR ' + menuGesamtpreis.toFixed(2) + '</td></tr>'
  +     '<tr><td style="padding:6px 0;color:#666;border-bottom:1px solid #ddd;">Verwaltungspauschale:</td><td style="padding:6px 0;text-align:right;border-bottom:1px solid #ddd;">EUR ' + pauschale.toFixed(2) + '</td></tr>'
  +     '<tr><td style="padding:8px 0;font-weight:bold;font-size:16px;">GESAMTPREIS:</td><td style="padding:8px 0;text-align:right;font-weight:bold;font-size:16px;">EUR ' + totalCosts.toFixed(2) + '</td></tr>'
  +     '<tr><td style="padding:6px 0;color:#666;">Budget:</td><td style="padding:6px 0;text-align:right;">EUR ' + Number(budget).toFixed(2) + '</td></tr>'
  +     '<tr><td style="padding:10px 0;color:#666;">Budget eingehalten:</td><td style="padding:10px 0;text-align:right;">' + budgetBadge + '</td></tr>'
  +   '</table>'
  +   sectionHeader('Begruendung der Auswahl')
  +   '<div style="background:#f8f9fa;border-left:4px solid #2c3e50;padding:14px 16px;font-size:14px;line-height:1.6;color:#333;">'
  +     escapeHtml(summary.reason || '(keine)').replace(/\n/g, '<br>')
  +   '</div>'
  + '</div>';

return [{ json: Object.assign({}, summary, { emailBody: emailBody, state }) }];

