const summary = $('Vorschlag aufbereiten').first().json;
const state = summary.state;
const anfrage = state.anfrage;
const telegramMessage = $('Telegram Trigger').first().json.message;

const orderMenuItems = summary.proposal.map(function(p) {
  return {
    menuItemId: p.menuItemId,
    name: p.name,
    category: p.category,
    count: p.count,
    pricePerPerson: p.pricePerPerson,
    totalPrice: p.totalPrice
  };
});

const backendPayload = {
  customer: {
    name: telegramMessage.from.first_name,
    telegramChatId: telegramMessage.chat.id
  },
  orderMenuItems: orderMenuItems,
  guestCount: anfrage.personenanzahl,
  budget: anfrage.budget,
  totalCosts: summary.totalCosts,
  dishWishes: anfrage.speisen_wuensche || '',
  specialWishes: anfrage.sonstige_wuensche || '',
  allergies: anfrage.allergien || '',
  date: anfrage.datum_iso,
  time: anfrage.uhrzeit_iso || null,
  eventType: anfrage.anlass || null,
  location: anfrage.ort || null
};

return [{ json: { backendPayload } }];

const fallbacks = [
  "Hmm, da habe ich gerade kurz den Faden verloren – magst du das nochmal etwas anders formulieren?",
  "Entschuldige, das habe ich nicht ganz verstanden. Kannst du mir das nochmal erklären?",
  "Oh, da bin ich gerade nicht ganz mitgekommen. Könntest du das nochmal anders schreiben?",
  "Sorry, das ist bei mir nicht ganz angekommen – wie meinst du das genau?",
  "Da muss ich kurz nachfragen: Magst du das nochmal in anderen Worten sagen?"
];

const randomFallback = fallbacks[Math.floor(Math.random() * fallbacks.length)];

return [{
  json: {
    fallback_text: randomFallback
  }
}];
